#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

// Create new node
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// Insert at beginning
struct Node* insertBeginning(struct Node* head, int value) {
    struct Node* newNode = createNode(value);

    if (head == NULL) {
        newNode->next = newNode;
        return newNode;
    }

    struct Node* temp = head;
    while (temp->next != head)
        temp = temp->next;

    temp->next = newNode;
    newNode->next = head;
    head = newNode;

    return head;
}

// Insert at end
struct Node* insertEnd(struct Node* head, int value) {
    struct Node* newNode = createNode(value);

    if (head == NULL) {
        newNode->next = newNode;
        return newNode;
    }

    struct Node* temp = head;
    while (temp->next != head)
        temp = temp->next;

    temp->next = newNode;
    newNode->next = head;

    return head;
}

// Insert at specific position
struct Node* insertAtPosition(struct Node* head, int value, int pos) {
    struct Node* newNode = createNode(value);

    if (pos == 1)
        return insertBeginning(head, value);

    if (head == NULL) {
        printf("Position out of range (list empty)\n");
        free(newNode);
        return head;
    }

    struct Node* temp = head;
    for (int i = 1; i < pos - 1 && temp->next != head; i++)
        temp = temp->next;

    if (temp->next == head && pos > 2) {
        printf("Position out of range!\n");
        free(newNode);
        return head;
    }

    newNode->next = temp->next;
    temp->next = newNode;

    return head;
}

// Delete by value
struct Node* deleteNode(struct Node* head, int value) {
    if (head == NULL) {
        printf("List is empty.\n");
        return head;
    }

    struct Node* current = head;
    struct Node* prev = NULL;

    // If only one node
    if (head->next == head && head->data == value) {
        free(head);
        printf("Deleted %d\n", value);
        return NULL;
    }

    // If head is to be deleted
    if (head->data == value) {
        struct Node* temp = head;
        while (temp->next != head)
            temp = temp->next;
        temp->next = head->next;
        struct Node* newHead = head->next;
        free(head);
        printf("Deleted %d\n", value);
        return newHead;
    }

    // Traverse to find node
    do {
        prev = current;
        current = current->next;
    } while (current != head && current->data != value);

    if (current == head) {
        printf("Value not found.\n");
        return head;
    }

    prev->next = current->next;
    free(current);
    printf("Deleted %d\n", value);
    return head;
}

// Display list
void display(struct Node* head) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }

    struct Node* temp = head;
    printf("Circular List: ");
    do {
        printf("%d -> ", temp->data);
        temp = temp->next;
    } while (temp != head);
    printf("(head)\n");
}

// Count nodes
int countNodes(struct Node* head) {
    if (head == NULL)
        return 0;

    int count = 0;
    struct Node* temp = head;
    do {
        count++;
        temp = temp->next;
    } while (temp != head);
    return count;
}

// Main
int main() {
    struct Node* head = NULL;
    int choice, value, pos;

    while (1) {
        printf("\n------ CIRCULAR LINKED LIST MENU ------\n");
        printf("1. Insert at Beginning\n");
        printf("2. Insert at End\n");
        printf("3. Insert at Position\n");
        printf("4. Delete by Value\n");
        printf("5. Display\n");
        printf("6. Count Nodes\n");
        printf("7. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter value: ");
                scanf("%d", &value);
                head = insertBeginning(head, value);
                break;

            case 2:
                printf("Enter value: ");
                scanf("%d", &value);
                head = insertEnd(head, value);
                break;

            case 3:
                printf("Enter value and position: ");
                scanf("%d %d", &value, &pos);
                head = insertAtPosition(head, value, pos);
                break;

            case 4:
                printf("Enter value to delete: ");
                scanf("%d", &value);
                head = deleteNode(head, value);
                break;

            case 5:
                display(head);
                break;

            case 6:
                printf("Total nodes: %d\n", countNodes(head));
                break;

            case 7:
                printf("Exiting program.\n");
                exit(0);

            default:
                printf("Invalid choice!\n");
        }
    }

    return 0;
}

